import { useEffect, useState } from "react";
import type { Locale } from "@/i18n/config";
import type { EmbroideryImage, PlacementId } from "../model/types";
import { LIBRARY_URL } from "./root";

/**
 * THE READY-MADE EMBROIDERY LIBRARY — designs a customer can put in a zone
 * instead of uploading their own.
 *
 * The data is <library>/library.json (root.ts: served from
 * runtime-assets/embroidery-library, not from public/), generated by
 * scripts/import-embroidery-library.mjs from the licensed source catalog
 * (the test subset: scripts/embroidery-fixtures/build.mjs). Each design is
 * recorded ONCE, with the zones it may go in; its files live once under
 * <library>/assets/<designId>/. The picker shows a
 * design in every zone it allows. Nothing is loaded until the picker opens:
 * the data file then, thumbnails as they scroll into view, the full file only
 * when a design is chosen.
 */

export type LibraryDesign = {
  /** Stable JACKETEK id ("ojisan:<designId>"). Never a file name. */
  id: string;
  designId: string;
  libraryId: string;
  libraryTitle: string;
  libraryDescription: string;
  /** The source's production / lab code for the library. */
  productionName: string | null;
  originalFileName: string | null;
  /** Local paths, served from public/: the original artwork, and the generated picker thumbnail. */
  asset: string;
  thumbnail: string;
  thumbnailWidth?: number;
  thumbnailHeight?: number;
  format: string;
  width: number;
  height: number;
  transparent: boolean;
  /** The JACKETEK zones it may go in (from the source's placement metadata). */
  zones: PlacementId[];
  source: { provider: string; libraryId: string; designId: string; placements: number[]; fullSleeve: boolean; fullUrl: string; thumbnailUrl: string };
};

export type LibraryCategory = {
  id: string;
  /** The source's own title (any language). */
  title: string;
  /** Titles per site language, when the data has them (otherwise `title` shows). */
  titles?: Partial<Record<Locale, string>>;
  description: string;
  productionName: string | null;
  designCount: number;
};

/** A category's title in the site's language, else its own. */
export const categoryTitle = (c: Pick<LibraryCategory, "title" | "titles">, locale: Locale) => c.titles?.[locale] ?? c.title;

export type LibraryData = { version: number; generated: string; libraries: LibraryCategory[]; designs: LibraryDesign[] };

const EMPTY: LibraryData = { version: 1, generated: "", libraries: [], designs: [] };
let request: Promise<LibraryData> | null = null;

/** The library data, fetched once (an absent file = an empty library). */
export function loadLibrary(): Promise<LibraryData> {
  request ??= fetch(`${LIBRARY_URL}/library.json`)
    .then((r) => (r.ok ? (r.json() as Promise<LibraryData>) : EMPTY))
    .catch(() => EMPTY);
  return request;
}

/** The library, loaded on first use (`null` while loading). */
export function useLibrary(enabled = true): LibraryData | null {
  const [data, setData] = useState<LibraryData | null>(null);
  useEffect(() => {
    if (!enabled) return;
    let live = true;
    loadLibrary().then((d) => live && setData(d));
    return () => {
      live = false;
    };
  }, [enabled]);
  return data;
}

/** Designs allowed in a zone. */
export const designsForZone = (data: LibraryData, zone: PlacementId) => data.designs.filter((d) => d.zones.includes(zone));

/**
 * A library design as a zone design's image: its own file (unchanged — the
 * existing pipeline fits, stitches and produces it like an upload), plus the
 * reference the order keeps.
 */
export function libraryImage(design: LibraryDesign): EmbroideryImage {
  return {
    src: design.asset,
    aspect: design.width / design.height,
    asUploaded: true,
    original: {
      fileName: design.originalFileName ?? `${design.designId}.${design.format}`,
      mimeType: design.format === "png" ? "image/png" : `image/${design.format}`,
      widthPx: design.width,
      heightPx: design.height,
    },
    library: {
      id: design.id,
      designId: design.designId,
      libraryId: design.libraryId,
      libraryTitle: design.libraryTitle,
      productionName: design.productionName,
      originalFileName: design.originalFileName,
      asset: design.asset,
      thumbnail: design.thumbnail,
      source: { provider: design.source.provider, placements: design.source.placements },
    },
  };
}
